<?php
namespace App\Jobs;use App\Models\BackupRestoreRun;use Illuminate\Bus\Queueable;use Illuminate\Contracts\Queue\ShouldQueue;use Illuminate\Foundation\Bus\Dispatchable;use Illuminate\Queue\InteractsWithQueue;use Illuminate\Queue\SerializesModels;use Illuminate\Support\Facades\Storage;use RuntimeException;use Symfony\Component\Process\Process;
class RestoreHotelBackup implements ShouldQueue{use Dispatchable,InteractsWithQueue,Queueable,SerializesModels;public int $timeout=1200;public function __construct(public int $restoreId){}public function handle():void{$run=BackupRestoreRun::with('backup')->findOrFail($this->restoreId);$run->update(['status'=>'running','started_at'=>now()]);$tmp=storage_path('app/tmp/hms-restore-'.$run->id);try{$b=$run->backup;if(!$b||$b->status!=='successful'||!$b->path)throw new RuntimeException('Only verified successful backups may be restored.');$disk=$b->disk?:config('filesystems.default');if(!Storage::disk($disk)->exists($b->path))throw new RuntimeException('Backup archive is missing from storage.');if(!is_dir($tmp))mkdir($tmp,0770,true);$archive=$tmp.'/backup.tar.gz';file_put_contents($archive,Storage::disk($disk)->get($b->path));if($b->checksum&&hash_file('sha256',$archive)!==$b->checksum)throw new RuntimeException('Backup checksum verification failed.');$p=new Process(['tar','-xzf',$archive,'-C',$tmp]);$p->mustRun();$manifest=$tmp.'/manifest.json';if(!is_file($manifest))throw new RuntimeException('Backup manifest missing.');if($run->dry_run){$run->update(['status'=>'successful','finished_at'=>now(),'message'=>'Dry-run verified archive, checksum and manifest. No data changed.']);return;}$sql=$tmp.'/database.sql';if(is_file($sql)){ $cfg=config('database.connections.'.config('database.default'));$cmd=['mysql','-h',(string)$cfg['host'],'-P',(string)($cfg['port']??3306),'-u',(string)$cfg['username']];if(!empty($cfg['password']))$cmd[]='--password='.(string)$cfg['password'];$cmd[]=(string)$cfg['database'];$p=new Process($cmd);$p->setInput(file_get_contents($sql));$p->setTimeout(900);$p->mustRun();}$run->update(['status'=>'successful','finished_at'=>now(),'message'=>'Restore completed. File payload restoration should be enabled only during a maintenance window after a tested recovery drill.']);}catch(\Throwable $e){$run->update(['status'=>'failed','finished_at'=>now(),'message'=>mb_substr($e->getMessage(),0,2000)]);throw $e;}finally{if(is_dir($tmp))(new Process(['rm','-rf',$tmp]))->run();}}}
